"""Write ios-oogo/Oogo/Config.swift from environment variables.

Config.swift is gitignored: Rork generated it at build time. CI recreates it
with the same shape, filling values from repository secrets (empty if unset).
Usage: python3 write_config.py <output path>
"""

import json
import os
import sys

NAMES = [
    "EXPO_PUBLIC_PROJECT_ID",
    "EXPO_PUBLIC_RORK_APP_KEY",
    "EXPO_PUBLIC_RORK_AUTH_URL",
    "EXPO_PUBLIC_SUPABASE_ANON_KEY",
    "EXPO_PUBLIC_SUPABASE_URL",
]


def swift_string(value: str) -> str:
    # JSON string escaping is valid Swift string literal escaping for these values.
    return json.dumps(value)


def main() -> None:
    out = sys.argv[1]
    lines = [
        "// Config.swift - generated by .github/scripts/write_config.py. Do not commit.",
        "",
        "import Foundation",
        "",
        "enum Config {",
    ]
    for name in NAMES:
        lines.append(f"    nonisolated static let {name} = {swift_string(os.environ.get(name, ''))}")
    lines += ["", "    nonisolated static let allValues: [String: String] = ["]
    for name in NAMES:
        lines.append(f'        "{name}": {name},')
    lines += ["    ]", "}", ""]
    with open(out, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    filled = [n for n in NAMES if os.environ.get(n)]
    print(f"Wrote {out} ({len(filled)}/{len(NAMES)} values set)")


if __name__ == "__main__":
    main()
